	const seen = new Set(stated.map((row) => drugCore(row.name)));
	const rows = [...stated];
	for (const row of memoryMedications(dataDir)) {
		const key = drugCore(row.name);
		if (seen.has(key)) continue;
		seen.add(key);
		rows.push(row);
	}
